import { evaluate } from "@/lib/content/expr";
import { clean, fmt, isWhole, makeRng, pick, pickInt, seedFromString, shuffled, type Rng } from "./rng";
import type { ChartSpec, ChoiceDrill, Drill, NumericDrill } from "./types";

// Chart-reading drills are generated by code: the numbers come from a seeded
// generator and every answer is computed from the plotted data.

const PER_FAMILY = 15;

const BAR_TOPICS = [
  { title: "Revenue by region", unit: "$ million", labels: ["North", "South", "East", "West", "Central"] },
  { title: "Customers by channel", unit: "thousand", labels: ["Online", "Stores", "Phone", "Partners", "Events"] },
  { title: "Costs by department", unit: "$ million", labels: ["Sales", "Operations", "Marketing", "IT", "Finance"] },
  { title: "Units sold by product", unit: "thousand", labels: ["Basic", "Plus", "Pro", "Max", "Mini"] },
  { title: "Visits by traffic source", unit: "thousand", labels: ["Search", "Social", "Email", "Direct", "Referral"] },
];

const LINE_TOPICS = [
  { title: "Annual revenue", unit: "$ million" },
  { title: "Active users", unit: "thousand" },
  { title: "Units shipped", unit: "thousand" },
  { title: "Annual profit", unit: "$ million" },
];

function barChart(rng: Rng, total: number, count: number, step: number): ChartSpec {
  const topic = pick(rng, BAR_TOPICS);
  // Split `total` into `count` positive parts, each a multiple of `step`.
  const units = total / step;
  const parts: number[] = Array(count).fill(1);
  for (let left = units - count; left > 0; left--) parts[pickInt(rng, 0, count - 1)]++;
  const labels = shuffled(rng, topic.labels).slice(0, count);
  return {
    kind: "bar",
    title: topic.title,
    unit: topic.unit,
    points: labels.map((label, i) => ({ label, value: parts[i] * step })),
  };
}

function sharePct(chart: ChartSpec, index: number) {
  const total = chart.points.reduce((sum, p) => sum + p.value, 0);
  return { total, value: chart.points[index].value };
}

function numeric(id: string, title: string, prompt: string, unit: string, expression: string, inputs: Record<string, number>, chart: ChartSpec, explanation: (a: number) => string, tolerancePct = 1): NumericDrill {
  const answer = clean(evaluate(expression, inputs));
  return { id, category: "chart-reading", kind: "numeric", title, prompt, unit, answer, tolerancePct, explanation: explanation(answer), expression, inputs, chart };
}

function shareDrills(): Drill[] {
  const rng = makeRng(seedFromString("chart-reading:share"));
  const out: Drill[] = [];
  const seen = new Set<string>();
  let guard = 0;
  while (out.length < PER_FAMILY && guard++ < 2000) {
    const [total, step] = pick(rng, [[100, 5], [200, 10], [400, 20]] as const);
    const chart = barChart(rng, total, pickInt(rng, 4, 5), step);
    const index = pickInt(rng, 0, chart.points.length - 1);
    const { total: sum, value } = sharePct(chart, index);
    const target = chart.points[index].label;
    const key = JSON.stringify(chart.points) + target;
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(
      numeric(
        `cr-share-${String(out.length + 1).padStart(2, "0")}`,
        "Share of a total",
        `What share of the total does "${target}" represent?`,
        "%",
        "value / total * 100",
        { value, total: sum },
        chart,
        (a) => `The bars add up to ${fmt(sum)} ${chart.unit}. ${target} is ${fmt(value)}, so ${fmt(value)} / ${fmt(sum)} = ${fmt(a)}%. Add the bars first, then divide.`,
      ),
    );
  }
  return out;
}

function differenceDrills(): Drill[] {
  const rng = makeRng(seedFromString("chart-reading:difference"));
  const out: Drill[] = [];
  const seen = new Set<string>();
  let guard = 0;
  while (out.length < PER_FAMILY && guard++ < 2000) {
    const [total, step] = pick(rng, [[100, 5], [200, 10], [400, 20]] as const);
    const chart = barChart(rng, total, pickInt(rng, 4, 5), step);
    const values = chart.points.map((p) => p.value);
    const high = Math.max(...values);
    const low = Math.min(...values);
    if (values.filter((v) => v === high).length > 1 || values.filter((v) => v === low).length > 1) continue;
    const key = JSON.stringify(chart.points);
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(
      numeric(
        `cr-gap-${String(out.length + 1).padStart(2, "0")}`,
        "Gap between highest and lowest",
        `How much bigger is the largest bar than the smallest bar? (${chart.unit})`,
        chart.unit,
        "high - low",
        { high, low },
        chart,
        (a) => `Largest = ${fmt(high)}, smallest = ${fmt(low)}, so the gap is ${fmt(a)} ${chart.unit}.`,
        1,
      ),
    );
  }
  return out;
}

function growthSeries(rng: Rng): { start: number; end: number; values: number[] } | null {
  const start = pick(rng, [40, 50, 80, 100, 120, 200]);
  const growth = pick(rng, [20, 25, 40, 50, 60, 75, 100]);
  const end = (start * (100 + growth)) / 100;
  if (!isWhole(end)) return null;
  // Four steps from start to end, uneven but always rising, in whole numbers.
  const mid = [0.25, 0.5, 0.75].map((f) => start + Math.round(((end - start) * (f + (rng() - 0.5) * 0.2)) / 5) * 5);
  const values = [start, ...mid.sort((a, b) => a - b), end];
  for (let i = 1; i < values.length; i++) if (values[i] <= values[i - 1]) return null;
  return { start, end, values };
}

function lineChart(rng: Rng, values: number[]): ChartSpec {
  const topic = pick(rng, LINE_TOPICS);
  return {
    kind: "line",
    title: topic.title,
    unit: topic.unit,
    points: values.map((value, i) => ({ label: `Year ${i + 1}`, value })),
  };
}

function growthDrills(): Drill[] {
  const rng = makeRng(seedFromString("chart-reading:growth"));
  const out: Drill[] = [];
  const seen = new Set<string>();
  let guard = 0;
  while (out.length < PER_FAMILY && guard++ < 2000) {
    const series = growthSeries(rng);
    if (!series) continue;
    const key = series.values.join(",");
    if (seen.has(key)) continue;
    seen.add(key);
    const chart = lineChart(rng, series.values);
    out.push(
      numeric(
        `cr-growth-${String(out.length + 1).padStart(2, "0")}`,
        "Growth across the chart",
        `By what percentage did the value grow between Year 1 and Year 5?`,
        "%",
        "(end - start) / start * 100",
        { start: series.start, end: series.end },
        chart,
        (a) => `Year 1 = ${fmt(series.start)}, Year 5 = ${fmt(series.end)}. Growth = (${fmt(series.end)} - ${fmt(series.start)}) / ${fmt(series.start)} = ${fmt(a)}%.`,
      ),
    );
  }
  return out;
}

function fastestYearDrills(): Drill[] {
  const rng = makeRng(seedFromString("chart-reading:fastest"));
  const out: Drill[] = [];
  const seen = new Set<string>();
  let guard = 0;
  while (out.length < PER_FAMILY && guard++ < 4000) {
    const series = growthSeries(rng);
    if (!series) continue;
    const rises = series.values.slice(1).map((v, i) => v - series.values[i]);
    const best = Math.max(...rises);
    if (rises.filter((r) => r === best).length > 1) continue;
    const key = series.values.join(",");
    if (seen.has(key)) continue;
    seen.add(key);
    const chart = lineChart(rng, series.values);
    const bestIndex = rises.indexOf(best);
    const options = rises.map((_, i) => `Year ${i + 1} to Year ${i + 2}`);
    const drill: ChoiceDrill = {
      id: `cr-fastest-${String(out.length + 1).padStart(2, "0")}`,
      category: "chart-reading",
      kind: "choice",
      title: "Spotting the biggest rise",
      prompt: "In which period did the value increase by the largest amount?",
      options,
      answerIndex: bestIndex,
      explanation: `The rises were ${rises.map((r, i) => `${options[i]}: +${fmt(r)}`).join("; ")}. The biggest is ${options[bestIndex]} (+${fmt(best)}). Compare the size of each step, not the height of the line.`,
      chart,
    };
    out.push(drill);
  }
  return out;
}

/** 60 chart-reading drills. */
export function generateChartDrills(): Drill[] {
  const lists = [shareDrills(), differenceDrills(), growthDrills(), fastestYearDrills()];
  const out: Drill[] = [];
  for (let i = 0; i < PER_FAMILY; i++) for (const list of lists) if (list[i]) out.push(list[i]);
  return out;
}
